std::wstring hardwareInfo;unsigned hardwareCores=1;unsigned long long totalRam=0;double systemCpu=0;ULONGLONG lastWarning=0;int pressureSamples=0;
void detectHardware(){SYSTEM_INFO si{};GetNativeSystemInfo(&si);hardwareCores=std::max<DWORD>(1,si.dwNumberOfProcessors);MEMORYSTATUSEX m{sizeof(m)};GlobalMemoryStatusEx(&m);totalRam=m.ullTotalPhys;DISPLAY_DEVICEW display{sizeof(display)};EnumDisplayDevicesW(nullptr,0,&display,0);hardwareInfo=std::to_wstring(hardwareCores)+tr(L" threads CPU / ",L" CPU threads / ")+std::to_wstring(totalRam/(1024*1024*1024))+L" GB RAM\r\n"+display.DeviceString;recordLog(L"HARDWARE",hardwareInfo);}
bool isStillImage(const std::wstring&f){auto ext=pv::key(std::filesystem::path(f).extension().u8string());return ext==".png"||ext==".jpg"||ext==".jpeg"||ext==".webp"||ext==".bmp";}
bool shouldOptimize(const pv::VideoSize&s){return pv::needsOptimization(s,hardwareCores,totalRam);}
void performanceWarning(){static unsigned long long k0=0,u0=0,i0=0;FILETIME i,k,u;auto v=[](FILETIME t){return (uint64_t(t.dwHighDateTime)<<32)|t.dwLowDateTime;};if(GetSystemTimes(&i,&k,&u)){auto kv=v(k),uv=v(u),iv=v(i);if(k0&&kv+uv>k0+u0)systemCpu=100.*(double(kv-k0+uv-u0)-double(iv-i0))/double(kv-k0+uv-u0);k0=kv;u0=uv;i0=iv;}
 MEMORYSTATUSEX m{sizeof(m)};GlobalMemoryStatusEx(&m);bool high=playing&&(systemCpu>85||cpu>35||m.ullAvailPhys<512ull*1024*1024);pressureSamples=high?pressureSamples+1:0;if(pressureSamples>=4&&GetTickCount64()-lastWarning>90000){lastWarning=GetTickCount64();companionTip(tr(L"Olha, a CPU tá subindo ou a memória está curta. Quer trocar o vídeo? Abra a Galeria e escolha uma cópia mais leve.",L"CPU is rising or memory is low. Want to change the video? Open Gallery and choose a lighter copy."));recordLog(L"PERFORMANCE",L"High pressure warning shown after four samples");}
 PROCESS_MEMORY_COUNTERS mem{sizeof(mem)};GetProcessMemoryInfo(GetCurrentProcess(),&mem,sizeof(mem));std::wostringstream t;t<<std::fixed<<std::setprecision(1)<<L"CPU app: "<<cpu<<L"%\r\nCPU "<<tr(L"sistema: ",L"system: ")<<systemCpu<<L"%\r\nRAM app: "<<mem.WorkingSetSize/1048576.<<L" MB\r\nRAM "<<tr(L"livre: ",L"free: ")<<m.ullAvailPhys/1048576.<<L" MB\r\n";if(playing)t<<L"GPU: "<<fromUtf8(player.text("hwdec-current"))<<L"\r\n";t<<hardwareInfo;renderInfo=t.str();}
std::vector<std::wstring> thumbnailsPending;std::wstring thumbnailInput;
std::wstring posterFileFor(const std::wstring&f){for(auto&i:playerCatalog.items)if(fromUtf8(i.path)==f&&!i.thumbnail.empty()&&GetFileAttributesW(fromUtf8(i.thumbnail).c_str())!=INVALID_FILE_ATTRIBUTES)return fromUtf8(i.thumbnail);return L"";}
void queueThumbnails(){for(auto&i:playerCatalog.items){auto p=fromUtf8(i.path);if(!i.thumbnail.empty()&&GetFileAttributesW(fromUtf8(i.thumbnail).c_str())!=INVALID_FILE_ATTRIBUTES)continue;if(GetFileAttributesW(p.c_str())!=INVALID_FILE_ATTRIBUTES&&std::find(thumbnailsPending.begin(),thumbnailsPending.end(),p)==thumbnailsPending.end()&&p!=thumbnailInput)thumbnailsPending.push_back(p);}}
void pollThumbnails(){if(thumbnailJob.busy()||thumbnailsPending.empty()||media.busy()||imageTask.busy())return;thumbnailInput=thumbnailsPending.front();thumbnailsPending.erase(thumbnailsPending.begin());auto folder=std::filesystem::path(iniPath).parent_path()/L"Thumbnails";auto file=folder/(std::to_wstring(GetTickCount64())+L"-"+std::to_wstring(GetCurrentProcessId())+L".png");thumbnailJob.thumbnail(window,baseDir+L"\\ferramentas",thumbnailInput,file.wstring());}
void thumbnailFinished(){if(!thumbnailJob.busy())return;auto r=thumbnailJob.take();if(r.kind==MediaResult::Thumbnail){for(auto&i:playerCatalog.items)if(fromUtf8(i.path)==r.input)i.thumbnail=toUtf8(r.output);catalogSave();if(galleryWindow)populateGallery();InvalidateRect(window,nullptr,FALSE);}thumbnailInput.clear();pollThumbnails();}
void startRemoval(){if(imageTask.busy()||media.busy())return;std::wstring input=selected;if(!isStillImage(input)){wchar_t file[32768]{};OPENFILENAMEW of{sizeof(of)};of.hwndOwner=window;of.lpstrFile=file;of.nMaxFile=32768;of.lpstrFilter=L"PNG / JPEG / WebP\0*.png;*.jpg;*.jpeg;*.webp\0\0";of.Flags=OFN_FILEMUSTEXIST|OFN_NOCHANGEDIR;if(!GetOpenFileNameW(&of))return;input=file;}try{auto folder=std::filesystem::path(iniPath).parent_path()/L"Removed"/std::to_wstring(GetTickCount64());if(!imageTask.start(baseDir,folder,{{"input",toUtf8(input)}}))throw std::runtime_error("Python/rembg could not start");message=tr(L"Processando imagem... Isso pode usar bastante CPU por alguns segundos.",L"Processing image... This may use significant CPU for a few seconds.");companionTip(message);updateUi();}catch(const std::exception&e){imageTask.stop();error(fromUtf8(e.what()));}}
void pollRemoval(){int state=imageTask.poll();if(state==0||state==1)return;try{if(state!=2)throw std::runtime_error("Background removal failed or timed out; see worker.log");auto j=imageTask.result();if(j.value("status","")!="ok")throw std::runtime_error(j.value("error","rembg error"));selected=fromUtf8(j.at("output"));catalogAdd(selected);imageTask.stop();save();message=tr(L"PNG transparente salvo na Galeria. O original foi preservado.",L"Transparent PNG saved in Gallery. Original preserved.");companionTip(message);updateUi();}catch(const std::exception&e){imageTask.stop();error(fromUtf8(e.what()));}}
